import '@design-schema/lit';
import { html } from 'lit';
import type { SliderMark } from '@design-schema/lit';

const PRICE_MARKS: SliderMark[] = [
  { value: 0, label: 'Min' },
  { value: 250, label: '$250' },
  { value: 500, label: 'Max' },
];

html`
  <div style="inline-size: min(100%, 24rem)">
    <ds-slider
      label="Price range"
      name="price"
      min="0"
      max="500"
      step="10"
      .defaultValue=${[100, 350]}
      range
      .marks=${PRICE_MARKS ?? []}
    ></ds-slider>
  </div>
`;
